def read_line(port, timeout=2.0):
    """Read one line from a FIFO port with timeout. Returns str or None."""
    fd = None
    try:
        fd = os.open(DEV % port, os.O_RDONLY | os.O_NONBLOCK)
        buf = b""
        t0 = time.time()
        while time.time() - t0 < timeout:
