"""Robot daemon: sensor loop, odometry, radio log, command file interface.
Commands (one per line appended to /tmp/cmd): 
  wheels L R | stop | rot H | goto X Y | fwd DIST | tx MESSAGE | quit
State mirrored to /tmp/state.json; log /tmp/log.jsonl; radio /tmp/rx.log; events /tmp/events.log
"""
import rb, time, json, math, os, sys, threading, statistics
TICKS_PER_M = 3000.0
BEAM_DEG = 22.5
CMD = "/tmp/cmd"; STATE = "/tmp/state.json"; LOG = "/tmp/log.jsonl"; RXLOG = "/tmp/rx.log"; EV = "/tmp/events.log"

st = dict(x=0.0, y=0.0, h=0.0, hraw=0.0, encL=None, encR=None, scan=None, d0=0, d5=0, d11=0.0, tick=0, goal=0, here=0, t=0.0, wheels=(0,0), busy="")
lock = threading.Lock()
hbuf = []

def ev(msg):
    with open(EV, "a") as f: f.write("%.1f %s\n" % (time.time(), msg))

def set_wheels(l, r):
    rb.write_line(1, str(int(l))); rb.write_line(7, str(int(r))); st["wheels"] = (l, r)

def angdiff(a, b): return (a - b + 180) % 360 - 180

def cmean(vals):
    x = sum(math.cos(math.radians(v)) for v in vals); y = sum(math.sin(math.radians(v)) for v in vals)
    return math.degrees(math.atan2(y, x)) % 360

def sensor_loop():
    lastE = None
    while True:
        try:
            h = rb.heading(); 
            if h is not None:
                hbuf.append(h); del hbuf[:-4]
            eL = rb.d(9); eR = rb.d(6)   # d9 <-> d1 wheel ("L"), d6 <-> d7 wheel ("R")
            s = rb.scan(); d0 = rb.d(0); d5 = rb.d(5); d11 = rb.d(11); stt = rb.status()
            with lock:
                if hbuf: st["h"] = cmean(hbuf); st["hraw"] = hbuf[-1]
                if eL is not None and eR is not None:
                    eL = int(eL); eR = int(eR)
                    if lastE is not None:
                        dd = ((eL - lastE[0]) + (eR - lastE[1])) / 2.0 / TICKS_PER_M
                        st["x"] += dd * math.cos(math.radians(st["h"])); st["y"] += dd * math.sin(math.radians(st["h"]))
                    lastE = (eL, eR); st["encL"] = eL; st["encR"] = eR
                if s: st["scan"] = [None if v < 0 else v for v in s]
                if d0 is not None: st["d0"] = int(float(d0))
                if d5 is not None: st["d5"] = int(float(d5))
                if d11 is not None: st["d11"] = float(d11)
                if stt: st.update(tick=stt.get("tick",0), goal=stt.get("goal",0), here=stt.get("here",0))
                st["t"] = time.time()
                snap = dict(st)
            with open(STATE, "w") as f: json.dump(snap, f)
            with open(LOG, "a") as f: f.write(json.dumps(snap) + "\n")
        except Exception as e:
            ev("sensor_loop error: %r" % e); time.sleep(0.2)

def rx_loop():
    while True:
        try:
            m = rb.read_line(10, 1.0)
            if m: 
                with open(RXLOG, "a") as f: f.write("%.1f %s\n" % (time.time(), m))
                ev("RX: " + m)
        except Exception as e:
            ev("rx error %r" % e); time.sleep(0.5)

def get(k):
    with lock: return st[k]

def front_clear():
    s = get("scan")
    if not s: return 9
    vals = [v for i in (15, 0, 1) for v in [s[i]] if v is not None]
    return min(vals) if vals else 9

def rot(target, tol=5, timeout=12):
    t0 = time.time(); st["busy"] = "rot"
    while time.time() - t0 < timeout:
        d = angdiff(target, get("h"))
        if abs(d) <= tol: break
        sp = 40 if abs(d) > 45 else (25 if abs(d) > 15 else 15)
        if d > 0: set_wheels(sp, -sp)
        else: set_wheels(-sp, sp)
        time.sleep(0.08)
    set_wheels(0, 0); time.sleep(0.3); st["busy"] = ""
    ev("rot done target=%.0f h=%.1f" % (target, get("h")))

def fwd(dist, speed=100, stop_at=0.15, target_h=None, timeout=40):
    """drive forward dist meters keeping heading; stop if obstacle < stop_at or bump."""
    st["busy"] = "fwd"; x0, y0 = get("x"), get("y"); t0 = time.time(); reason = "dist"
    if target_h is None: target_h = get("h")
    while time.time() - t0 < timeout:
        gone = math.hypot(get("x") - x0, get("y") - y0)
        if gone >= dist: break
        fc = front_clear()
        if fc < stop_at: reason = "obstacle %.2f" % fc; break
        if get("d5"): reason = "bump"; break
        sp = speed if fc > 0.5 and dist - gone > 0.3 else min(speed, 50)
        corr = max(-15, min(15, 0.8 * angdiff(target_h, get("h"))))
        set_wheels(sp + corr, sp - corr)
        time.sleep(0.08)
    set_wheels(0, 0); time.sleep(0.2); st["busy"] = ""
    gone = math.hypot(get("x") - x0, get("y") - y0)
    ev("fwd done dist=%.2f gone=%.2f reason=%s pos=(%.2f,%.2f) h=%.0f" % (dist, gone, reason, get("x"), get("y"), get("h")))
    return reason

def goto(X, Y, stop_at=0.15):
    for _ in range(3):
        dx, dy = X - get("x"), Y - get("y"); dist = math.hypot(dx, dy)
        if dist < 0.08: ev("goto reached (%.2f,%.2f)" % (X, Y)); return "ok"
        th = math.degrees(math.atan2(dy, dx)) % 360
        rot(th)
        r = fwd(dist, target_h=th, stop_at=stop_at)
        if r != "dist": ev("goto aborted: " + r); return r
    return "ok"

def cmd_loop():
    pos = 0
    open(CMD, "a").close()
    while True:
        time.sleep(0.1)
        with open(CMD) as f:
            f.seek(pos); lines = f.readlines(); pos = f.tell()
        for line in lines:
            p = line.strip().split()
            if not p: continue
            ev("CMD: " + line.strip())
            try:
                if p[0] == "wheels": set_wheels(int(p[1]), int(p[2]))
                elif p[0] == "stop": set_wheels(0, 0)
                elif p[0] == "rot": rot(float(p[1]))
                elif p[0] == "goto": goto(float(p[1]), float(p[2]))
                elif p[0] == "fwd": fwd(float(p[1]), speed=int(p[2]) if len(p) > 2 else 100)
                elif p[0] == "tx": rb.tx(line.strip()[3:]); ev("TX: " + line.strip()[3:])
                elif p[0] == "setpos": 
                    with lock: st["x"], st["y"] = float(p[1]), float(p[2])
                elif p[0] == "quit": set_wheels(0, 0); os._exit(0)
            except Exception as e:
                ev("cmd error %r" % e); set_wheels(0, 0)

if __name__ == "__main__":
    threading.Thread(target=sensor_loop, daemon=True).start()
    threading.Thread(target=rx_loop, daemon=True).start()
    ev("daemon start")
    cmd_loop()
